import {
  Box,
  Stack,
  Typography,
  ToggleButton,
  ToggleButtonGroup,
} from "@mui/material";

import { alpha } from "@mui/material/styles";

import {
  FactCheckRounded,
} from "@mui/icons-material";

import ForecastContextBar from "../../../components/layout/ForecastContextBar";

import {
  useForecastContext,
} from "../../../contexts/ForecastContext";

import ModelPerformanceKPIs from "../components/ModelPerformanceKPIs";
import OotPerformanceChart from "../components/OotPerformanceChart";
import CumulativeBurnHistory from "../components/CumulativeBurnHistory";
import ModelAccuracyMatrix from "../components/ModelAccuracyMatrix";

import {
  PerformanceHorizon,
  PerformanceTarget,
} from "../types/model-performance.types";


/**
 * =====================================================
 * MODEL PERFORMANCE PAGE
 * =====================================================
 *
 * Existing:
 * - Forecast Context
 * - Evaluation View
 * - KPIs
 * - OOT Performance Chart
 * - Cumulative Metric History
 * - Model Accuracy Matrix
 *
 * The selected forecast metric is passed through to
 * the cumulative history chart so that:
 *
 * burn      -> Input_actual / Input_predicted
 * supply    -> Replenishment_actual / Replenishment_predicted
 * stockpile  -> Stockpile_actual / Stockpile_predicted
 */
const ModelPerformancePage = () => {

  const {
    horizon,
    metric,
    entityId,
    setHorizon,
  } = useForecastContext();


  /*
   * -----------------------------------------------------
   * FORECAST HORIZON
   * -----------------------------------------------------
   *
   * daily   -> tactical
   * monthly -> strategic
   */

  const performanceHorizon:
    PerformanceHorizon =
    horizon === "monthly"
      ? "monthly"
      : "daily";


  /*
   * -----------------------------------------------------
   * FORECAST METRIC
   * -----------------------------------------------------
   *
   * burn      -> Input
   * supply    -> Replenishment
   * stockpile -> Stockpile
   */

  const target:
    PerformanceTarget =
    metric === "supply"
      ? "Replenishment"
      : metric === "stockpile"
      ? "Stockpile"
      : "Input";


  const ootMetric:
    | "Input"
    | "Replenishment"
    | "Stockpile" =
    target;


  return (

    <Box
      sx={{
        width: "100%",
        minHeight: "100%",
        boxSizing: "border-box",
      }}
    >

      <Stack spacing={3}>

        {/* ================================================= */}
        {/* FORECAST CONTEXT                                  */}
        {/* ================================================= */}

        <ForecastContextBar />


        {/* ================================================= */}
        {/* EVALUATION VIEW                                  */}
        {/* ================================================= */}

        <Box
          sx={{
            bgcolor:
              "background.paper",

            border:
              "1px solid #E4EAF3",

            borderRadius: "12px",

            boxShadow:
              "0 10px 30px rgba(16,32,62,0.05)",

            px: {
              xs: 2.5,
              md: 4,
            },

            py: 2.25,

            display: "flex",

            flexWrap: "wrap",

            justifyContent:
              "space-between",

            alignItems: "center",

            gap: 2,
          }}
        >

          <Stack
            direction="row"
            spacing={1.5}
            alignItems="center"
            sx={{
              minWidth: 0,
            }}
          >

            <Box
              sx={{
                width: 44,
                height: 44,
                borderRadius: "12px",

                display: "flex",
                alignItems: "center",
                justifyContent: "center",

                bgcolor: (t) =>
                  alpha(
                    t.palette.primary.main,
                    t.palette.mode === "dark"
                      ? 0.2
                      : 0.1
                  ),

                color:
                  "primary.main",
              }}
            >

              <FactCheckRounded />

            </Box>


            <Box
              sx={{
                minWidth: 0,
              }}
            >

              <Typography
                variant="subtitle1"
                fontWeight={800}
                color="text.primary"
              >
                Evaluation View
              </Typography>


              <Typography
                variant="body2"
                color="text.secondary"
              >
                Accuracy metrics for the
                selected forecast context.
              </Typography>

            </Box>

          </Stack>


          {/*
            * The two horizon buttons are separate, self-contained
            * pills (they used to be welded into one segmented block)
            * and they now drive the shared forecast context instead
            * of being read-only.
            */}

          <ToggleButtonGroup
            exclusive
            value={performanceHorizon}
            size="small"
            onChange={(
              _event,
              value
            ) => {
              if (value) {
                setHorizon(value);
              }
            }}
            sx={{
              flexShrink: 0,
              gap: 1,
            }}
          >

            <ToggleButton
              value="daily"
              sx={{
                fontWeight: 700,
                borderRadius: "10px !important",
              }}
            >
              Tactical Daily
            </ToggleButton>


            <ToggleButton
              value="monthly"
              sx={{
                fontWeight: 700,
                borderRadius: "10px !important",
              }}
            >
              Strategic Monthly
            </ToggleButton>

          </ToggleButtonGroup>

        </Box>


        {/* ================================================= */}
        {/* PERFORMANCE DASHBOARD                            */}
        {/* ================================================= */}

        <Stack
          spacing={3}
          minWidth={0}
        >

          {/* ================================================= */}
          {/* KPIs                                              */}
          {/* ================================================= */}

          <ModelPerformanceKPIs
            horizon={performanceHorizon}
            entityId={entityId}
          />


          {/* ================================================= */}
          {/* OOT PERFORMANCE                                  */}
          {/* ================================================= */}

          <OotPerformanceChart
            horizon={performanceHorizon}
            entityId={entityId}
            metric={ootMetric}
          />


          {/* ================================================= */}
          {/* CUMULATIVE METRIC HISTORY                        */}
          {/* ================================================= */}

          <CumulativeBurnHistory
            horizon={performanceHorizon}
            entityId={entityId}
            metric={ootMetric}
          />


          {/* ================================================= */}
          {/* MODEL ACCURACY MATRIX                             */}
          {/* ================================================= */}

          <ModelAccuracyMatrix
            horizon={performanceHorizon}
            entityId={entityId}
          />

        </Stack>

      </Stack>

    </Box>
  );
};


export default ModelPerformancePage;
